import { useState, useEffect } from "react";
import { Box, Typography, IconButton, Stack } from "@mui/material";
import PaletteIcon from "@mui/icons-material/Palette"; // Color picker icon

// Define color options for each variable
const COLOR_PALETTE = {
  "--main-bg": ["#1b1b1b", "#121212", "#333", "#555", "#000"],
  "--primary-bg": ["#333", "#444", "#555", "#666", "#777"],
  "--light-bg": ["gray", "#bbb", "#ddd", "#f5f5f5", "#fff"],
  "--main-text": ["#666", "#888", "#aaa", "#ccc", "#fff"],
  "--primary-text": ["black", "#222", "#444", "#666", "#888"],
  "--gold-hover": ["#ab844e", "#c79a5d", "#d4a15e", "#e5b873", "#f8cc8a"],
  "--border-color": ["#ccc", "#bbb", "#aaa", "#999", "#888"],
  "--shadow-color": ["rgba(0,0,0,0.1)", "rgba(0,0,0,0.2)", "rgba(0,0,0,0.3)", "rgba(0,0,0,0.4)", "rgba(0,0,0,0.5)"],
};

const MangeLayout = () => {
  const [selectedColors, setSelectedColors] = useState(() => {
    // Retrieve saved colors or use defaults
    const savedColors = JSON.parse(localStorage.getItem("selectedColors") || "{}");
    return Object.keys(COLOR_PALETTE).reduce((acc, key) => {
      acc[key] = savedColors[key] || COLOR_PALETTE[key][0]; // Use stored value or default
      return acc;
    }, {} );
  });

  useEffect(() => {
    // Apply saved colors to root
    Object.entries(selectedColors).forEach(([key, color]) => {
      document.documentElement.style.setProperty(key, color);
    });
  }, []);

  const handleColorChange = (variable, color) => {
    const newColors = { ...selectedColors, [variable]: color };
    setSelectedColors(newColors);
    
    // Save colors in localStorage properly
    localStorage.setItem("selectedColors", JSON.stringify(newColors));

    // Apply color to CSS variable
    document.documentElement.style.setProperty(variable, color);
  };
  return (
    <Box sx={{ textAlign: "center", mt: 3, display: 'flex', width: '100%', flexWrap: 'wrap', flexDirection: 'column' }}>
      <Typography variant="h6" sx={{ mb: 2 }}>🎨 Customize Your Theme</Typography>
      <Stack justifyContent='center' direction='row' flexWrap="wrap">
        {Object.keys(COLOR_PALETTE).map((variable) => (
          <Stack width='350px' key={variable} sx={{ mb: 3 }}>
            <Typography variant="body1">{variable.replace("--", "").replace("-", " ")}</Typography>
            
            {/* Predefined Color Circles */}
            <Box sx={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 1, mt: 1 }}>
              {COLOR_PALETTE[variable].map((color) => (
                <Box
                  key={color}
                  onClick={() => handleColorChange(variable, color)}
                  sx={{
                    width: 30,
                    height: 30,
                    borderRadius: "50%",
                    backgroundColor: color,
                    cursor: "pointer",
                    border: selectedColors[variable] === color ? "3px solid white" : "2px solid transparent",
                    transition: "transform 0.2s",
                    "&:hover": { transform: "scale(1.2)" },
                  }}
                />
              ))}
              {/* Custom Color Picker */}
              <IconButton component="label">
                <PaletteIcon />
                <input
                  type="color"
                  style={{ display: "none" }}
                  onChange={(e) => handleColorChange(variable, e.target.value)}
                />
              </IconButton>
            </Box>
          </Stack>
        ))}
      </Stack>
    </Box>
  );
};

export default MangeLayout;
